package com.on.ebx.connect.connectors;

import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.atomic.*;
import com.fasterxml.jackson.databind.JsonNode;import com.sun.net.httpserver.*;import com.on.ebx.connect.spi.*;

/** Offline signed HTTP fixture for SNS publish and read-only topic discovery. */
public final class SnsConnectorTest
{
	public static void main(final String[] args)throws Exception
	{System.setProperty("ebx.connectors.aws.accessKeyId","AKIDTEST");System.setProperty("ebx.connectors.aws.secretAccessKey","secret");final AtomicReference<String> request=new AtomicReference<String>();final HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",x->{final String body=SqsConnectorTestRead.read(x.getRequestBody());request.set(body);check(x.getRequestHeaders().getFirst("Authorization").contains("/sns/aws4_request"),"SigV4 service");final String answer=body.contains("ListTopics")?"<ListTopicsResponse><Topics><member><TopicArn>arn:aws:sns:us-east-1:1:governed</TopicArn></member></Topics><NextToken>next</NextToken></ListTopicsResponse>":"<PublishResponse><MessageId>pub1</MessageId></PublishResponse>";x.sendResponseHeaders(200,answer.length());x.getResponseBody().write(answer.getBytes("UTF-8"));x.close();});server.start();try{final SnsConnector c=new SnsConnector();final ConnectorConfig cfg=new ConnectorConfig();cfg.setId("sns-test");cfg.setType("amazon-sns");cfg.setProperty("endpoint","http://127.0.0.1:"+server.getAddress().getPort()+"/");cfg.setProperty("region","us-east-1");cfg.setProperty("topicArn","arn:aws:sns:us-east-1:1:governed");c.configure(cfg);JsonNode out=c.execute(null,"publish",map("message","hello","subject","Test"),null);check("pub1".equals(out.get("messageId").asText()),"publish");check(request.get().contains("Publish")&&request.get().contains("TopicArn"),"publish request");out=c.execute(null,"topics",Collections.<String,String>emptyMap(),null);check(out.get("topics").size()==1&&"next".equals(out.get("nextToken").asText()),"topics");check(c.getOperations().size()==2&&!request.get().contains("Subscribe"),"no subscription admin");check(c.getDescriptor().getDescription().contains("subscription administration is not exposed"),"scope disclosure");System.out.println("PASS: SNS signed bounded publish, topic discovery, pagination token, and no subscription administration");}finally{server.stop(0);System.clearProperty("ebx.connectors.aws.accessKeyId");System.clearProperty("ebx.connectors.aws.secretAccessKey");}}
	private static Map<String,String> map(final String...v){final Map<String,String>m=new LinkedHashMap<String,String>();for(int i=0;i<v.length;i+=2)m.put(v[i],v[i+1]);return m;}private static void check(final boolean b,final String m){if(!b)throw new AssertionError(m);}
}

final class SqsConnectorTestRead{static String read(final InputStream in)throws IOException{final ByteArrayOutputStream out=new ByteArrayOutputStream();final byte[]b=new byte[1024];for(int n;(n=in.read(b))>=0;)out.write(b,0,n);return new String(out.toByteArray(),"UTF-8");}}
